INSERT INTO product_catalog(category,name,price,active)
SELECT coalesce("Category",''),trim("Name"),coalesce(nullif(replace("Price",',',''),''),'0')::numeric,
  upper(trim(coalesce("Active",'Y'))) NOT IN ('N','NO','FALSE','0')
FROM jsonb_to_recordset('[{"Category":"Takoyaki","Name":"Veggies","Price":"40","Active":"Y"},{"Category":"Takoyaki","Name":"Cheese","Price":"45","Active":"Y"},{"Category":"Takoyaki","Name":"Bacon","Price":"55","Active":"Y"},{"Category":"Takoyaki","Name":"Crab","Price":"60","Active":"Y"},{"Category":"Takoyaki","Name":"Octo","Price":"60","Active":"Y"},{"Category":"Takoyaki","Name":"Bacon Melt Cheese","Price":"65","Active":"Y"},{"Category":"Takoyaki","Name":"Octo Melt Cheese","Price":"65","Active":"Y"},{"Category":"Takoyaki","Name":"Full Veggies","Price":"220","Active":"Y"},{"Category":"Takoyaki","Name":"Full Cheese","Price":"250","Active":"Y"},{"Category":"Takoyaki","Name":"Full Bacon","Price":"310","Active":"Y"},{"Category":"Takoyaki","Name":"Full Crab","Price":"340","Active":"Y"},{"Category":"Takoyaki","Name":"Full Octo","Price":"340","Active":"Y"},{"Category":"Takoyaki","Name":"Full Bacon Melt Cheese","Price":"370","Active":"Y"},{"Category":"Takoyaki","Name":"Full Octo Melt Cheese","Price":"370","Active":"Y"},{"Category":"Takoyaki","Name":"Full Assorted Flavors","Price":"350","Active":"Y"},{"Category":"Drinks","Name":"Thai Milk Tea","Price":50,"Active":"Y"}]'::jsonb) AS x("Category" text,"Name" text,"Price" text,"Active" text)
WHERE trim(coalesce("Name",''))<>'' ON CONFLICT(name) DO UPDATE SET category=excluded.category,price=excluded.price,active=excluded.active;

INSERT INTO users(username,password_hash,salt,role,active)
SELECT trim("Username"),coalesce("Password_Hash",''),coalesce("Salt",''),coalesce(nullif("Role",''),'staff'),
  upper(trim(coalesce("Active",'Y'))) NOT IN ('N','NO','FALSE','0')
FROM jsonb_to_recordset('[{"Username":"admin","Password_Hash":"7943cde905b9ddef65f415ca055c9246eebb4deb52b680e0004fa9da831b3566","Salt":"9f9b7b7e7c3f4c4b9e6a1c2d3e4f5a6b","Role":"admin","Active":"Y"},{"Username":"staff","Password_Hash":"7943cde905b9ddef65f415ca055c9246eebb4deb52b680e0004fa9da831b3566","Salt":"9f9b7b7e7c3f4c4b9e6a1c2d3e4f5a6b","Role":"staff","Active":"Y"}]'::jsonb) AS x("Username" text,"Password_Hash" text,"Salt" text,"Role" text,"Active" text)
WHERE trim(coalesce("Username",''))<>'' ON CONFLICT ((lower(trim(username)))) DO UPDATE SET password_hash=excluded.password_hash,salt=excluded.salt,role=excluded.role,active=excluded.active;

