INSERT INTO replenishment_needs(business_date,product,inventory_item_id,current_closing_qty,status)
SELECT left(x."Date",10)::date,trim(x."Product"),i.id,coalesce(nullif(replace(x."Current_Closing_Qty",',',''),''),'0')::numeric,coalesce(x."Status",'')
FROM jsonb_to_recordset('[{"Product":"Extension","Current_Closing_Qty":0,"Status":"NEEDS_MANUAL","Date":"2026-05-22T00:00:00.000Z"},{"Product":"test","Current_Closing_Qty":0,"Status":"NEEDS_MANUAL","Date":"2026-05-23T00:00:00.000Z"},{"Product":"Octo","Current_Closing_Qty":0,"Status":"NEEDS_MANUAL","Date":"2026-06-01T00:00:00.000Z"}]'::jsonb) AS x("Date" text,"Product" text,"Current_Closing_Qty" text,"Status" text)
LEFT JOIN inventory_items i ON i.product=trim(x."Product") WHERE trim(coalesce(x."Product",''))<>'' AND left(coalesce(x."Date",''),10) ~ '^\d{4}-\d{2}-\d{2}$'
ON CONFLICT(business_date,product,status) DO UPDATE SET inventory_item_id=excluded.inventory_item_id,current_closing_qty=excluded.current_closing_qty;

INSERT INTO app_config(key,value) SELECT trim("Key"),to_jsonb(coalesce("Value",''))
FROM jsonb_to_recordset('[{"Key":"sales_config","Value":"{\"expenseBreakdown\":[{\"key\":\"Breakdown_Allow\",\"label\":\"Allow\"},{\"key\":\"Breakdown_Ipon\",\"label\":\"Ipon\"},{\"key\":\"Breakdown_Bill\",\"label\":\"Bill\"},{\"key\":\"Breakdown_Ilaw\",\"label\":\"Ilaw\"}],\"partners\":[{\"key\":\"Payout_Mykah\",\"label\":\"Mykah\"},{\"key\":\"Payout_Natalie\",\"label\":\"Natalie\"}],\"staff\":[\"Nathalie\",\"Mykah\"],\"config\":{\"expenseBreakdown\":[{\"key\":\"Breakdown_Allow\",\"label\":\"Allow\"},{\"key\":\"Breakdown_Ipon\",\"label\":\"Ipon\"},{\"key\":\"Breakdown_Bill\",\"label\":\"Bill\"},{\"key\":\"Breakdown_Ilaw\",\"label\":\"Ilaw\"}],\"partners\":[{\"key\":\"Payout_Mykah\",\"label\":\"Mykah\"},{\"key\":\"Payout_Natalie\",\"label\":\"Natalie\"}],\"staff\":[\"Mykah\",\"Nathalie\"],\"config\":{\"expenseBreakdown\":[{\"key\":\"Breakdown_Allow\",\"label\":\"Allow\"},{\"key\":\"Breakdown_Ipon\",\"label\":\"Ipon\"},{\"key\":\"Breakdown_Bill\",\"label\":\"Bill\"},{\"key\":\"Breakdown_Ilaw\",\"label\":\"Ilaw\"}],\"partners\":[{\"key\":\"Payout_Mykah\",\"label\":\"Mykah\"},{\"key\":\"Payout_Natalie\",\"label\":\"Natalie\"}],\"staff\":[\"Mykah\"],\"config\":{\"expenseBreakdown\":[{\"key\":\"Breakdown_Allowance\",\"label\":\"Allowance\"},{\"key\":\"Breakdown_Bill\",\"label\":\"Bill\"},{\"key\":\"Breakdown_Ipon\",\"label\":\"Ipon\"},{\"key\":\"Breakdown_Ilaw\",\"label\":\"Ilaw\"},{\"key\":\"Breakdown_Egg\",\"label\":\"Ingredients\"},{\"key\":\"Breakdown_Rider_Delivery\",\"label\":\"Rider Delivery\"},{\"key\":\"Breakdown_Nawasa\",\"label\":\"Nawasa\"},{\"key\":\"Breakdown_Barangay_Contribution\",\"label\":\"Barangay Contribution\"},{\"key\":\"Breakdown_Other\",\"label\":\"Other\"}],\"partners\":[{\"key\":\"Payout_Mykah\",\"label\":\"\"},{\"key\":\"Payout_Natalie\",\"label\":\"Natalie\"}],\"staff\":[\"Nathalie\",\"Joy\",\"Boss\",\"Ma''am\"]}}}}"}]'::jsonb) AS x("Key" text,"Value" text) WHERE trim(coalesce("Key",''))<>''
ON CONFLICT(key) DO UPDATE SET value=excluded.value;

WITH source AS (SELECT left("Date",10)::date business_date,trim("Staff") staff,upper(trim(coalesce("On_Duty",''))) IN ('Y','YES','TRUE','1') on_duty
FROM jsonb_to_recordset('[]'::jsonb) AS x("Date" text,"Staff" text,"On_Duty" text)
WHERE trim(coalesce("Staff",''))<>'' AND left(coalesce("Date",''),10) ~ '^\d{4}-\d{2}-\d{2}$'), members AS (
INSERT INTO staff_members(display_name) SELECT DISTINCT staff FROM source ON CONFLICT(display_name) DO UPDATE SET display_name=excluded.display_name RETURNING id,display_name)
INSERT INTO attendance(business_date,staff_id,on_duty) SELECT s.business_date,m.id,s.on_duty FROM source s JOIN members m ON m.display_name=s.staff
ON CONFLICT(business_date,staff_id) DO UPDATE SET on_duty=excluded.on_duty;

COMMIT;
